var NCQ_IDEAS = [{"id":"IDEA_001","title_ru":"Отправиться в путешествие в одиночку","description_ru":"Провести несколько дней в новом месте, где ты сам решаешь, куда идти, когда менять планы и каким будет каждый день.","first_step_ru":"Выбери три места для самостоятельной поездки на 2–4 дня. Посмотри даты и билеты и найди вариант, который реально можешь забронировать.","category":"Travel","experience_type":"travel","impact":5,"accessibility":2,"novelty":5,"adventure":5,"travel":5,"physical":1,"learning":2,"creative":1,"social":1,"relationships":1,"courage":5,"freedom":5,"meaning":3,"budget":3,"time":1,"physical_level":3,"planning":3,"solo":true,"with_people":false,"travel_required":true,"active":true,"top1":true,"top2":false,"stretch":true,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"БОЛЬШЕ САМОСТОЯТЕЛЬНОСТИ"},{"id":"IDEA_002","title_ru":"Пожить в другой стране не как турист","description_ru":"Почувствовать, каково это — не путешествовать, а действительно жить в другой стране: со своим ритмом, привычными делами и обычными буднями.","first_step_ru":"Выбери город, в котором тебе хотелось бы попробовать пожить, и посмотри жильё на 2–4 недели в районе, где живут местные.","category":"Travel","experience_type":"travel","impact":5,"accessibility":2,"novelty":5,"adventure":5,"travel":5,"physical":1,"learning":4,"creative":2,"social":3,"relationships":2,"courage":4,"freedom":5,"meaning":4,"budget":4,"time":1,"physical_level":4,"planning":4,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":true,"top2":false,"stretch":true,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"СМЕНА СРЕДЫ"},{"id":"IDEA_003","title_ru":"Поехать туда, куда ты обычно не выбрал(а) бы","description_ru":"Выйти за рамки привычных маршрутов и дать шанс месту, которое раньше ты бы даже не рассматривал(а).","first_step_ru":"Выбери пять направлений, которые обычно не попадают в твой список, и найди среди них одно, которое неожиданно хочется открыть для себя.","category":"Adventure","experience_type":"travel","impact":5,"accessibility":2,"novelty":5,"adventure":5,"travel":5,"physical":1,"learning":2,"creative":1,"social":2,"relationships":1,"courage":4,"freedom":4,"meaning":2,"budget":3,"time":1,"physical_level":2,"planning":2,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"СЛОМАТЬ ПРИВЫЧНЫЙ ВЫБОР"},{"id":"IDEA_004","title_ru":"Устроить путешествие без подробного плана","description_ru":"Оставить место для спонтанности — не знать заранее весь маршрут и решать, куда двигаться дальше, уже по ходу поездки.","first_step_ru":"В следующей поездке запланируй только самое необходимое: дорогу и первые 1–2 ночи. Всё остальное решай уже на месте.","category":"Adventure","experience_type":"travel","impact":5,"accessibility":2,"novelty":5,"adventure":5,"travel":5,"physical":1,"learning":1,"creative":1,"social":2,"relationships":2,"courage":4,"freedom":5,"meaning":3,"budget":3,"time":1,"physical_level":1,"planning":1,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"БОЛЬШЕ СПОНТАННОСТИ"},{"id":"IDEA_005","title_ru":"Проехать маршрут, где дорога важнее точки назначения","description_ru":"Превратить сам путь в приключение — останавливаться в интересных местах, сворачивать с маршрута и не спешить к конечной точке.","first_step_ru":"Открой карту и придумай маршрут на 1–2 дня минимум с тремя остановками, ради которых стоит сделать крюк.","category":"Travel","experience_type":"travel","impact":5,"accessibility":2,"novelty":5,"adventure":5,"travel":5,"physical":1,"learning":1,"creative":2,"social":2,"relationships":3,"courage":3,"freedom":4,"meaning":3,"budget":3,"time":1,"physical_level":3,"planning":3,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":true,"top2":false,"stretch":false,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"СДЕЛАТЬ ДОРОГУ ПРИКЛЮЧЕНИЕМ"},{"id":"IDEA_006","title_ru":"Увидеть природное явление, ради которого стоит отправиться в путешествие","description_ru":"Увидеть своими глазами то, что обычно существует только на фотографиях: северное сияние, затмение, миграцию животных или другое редкое явление.","first_step_ru":"Выбери природное явление, которое хочешь увидеть, и узнай, где и когда шанс застать его особенно высок.","category":"Experience","experience_type":"travel","impact":5,"accessibility":2,"novelty":5,"adventure":4,"travel":5,"physical":1,"learning":3,"creative":1,"social":2,"relationships":2,"courage":3,"freedom":4,"meaning":3,"budget":3,"time":1,"physical_level":4,"planning":3,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":true,"top2":false,"stretch":false,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ПОЕХАТЬ РАДИ ОДНОГО МОМЕНТА"},{"id":"IDEA_007","title_ru":"Провести ночь в необычном месте","description_ru":"Сделать место ночёвки одним из главных впечатлений путешествия — таким, которое запомнится не меньше самой поездки.","first_step_ru":"Найди три необычных варианта для ночёвки: домик на дереве, лодку, маяк, глэмпинг в пустыне или что-то совсем неожиданное.","category":"Experience","experience_type":"travel","impact":5,"accessibility":2,"novelty":5,"adventure":4,"travel":4,"physical":1,"learning":1,"creative":3,"social":2,"relationships":3,"courage":2,"freedom":3,"meaning":3,"budget":2,"time":1,"physical_level":3,"planning":2,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"СМЕНИТЬ ОБЫЧНЫЙ СЦЕНАРИЙ"},{"id":"IDEA_008","title_ru":"Научиться серфингу","description_ru":"Не просто попробовать один раз, а поймать свою первую волну и почувствовать, каково это — действительно ехать на ней.","first_step_ru":"Найди серф-школу в месте, куда тебе реально добраться, и запланируй несколько занятий подряд — например, 3–5 уроков.","category":"Physical","experience_type":"sport_adventure","impact":5,"accessibility":2,"novelty":5,"adventure":5,"travel":4,"physical":5,"learning":5,"creative":1,"social":2,"relationships":1,"courage":4,"freedom":3,"meaning":3,"budget":3,"time":3,"physical_level":3,"planning":2,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":true,"top2":false,"stretch":true,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ОСВОИТЬ НОВЫЙ СПОРТ"},{"id":"IDEA_009","title_ru":"Освоить дайвинг","description_ru":"Научиться уверенно чувствовать себя под водой и открыть мир, который раньше можно было видеть только с поверхности.","first_step_ru":"Найди сертифицированный дайв-центр и начни с пробного погружения — а если понравится, запланируй курс Open Water.","category":"Skills","experience_type":"sport_adventure","impact":5,"accessibility":2,"novelty":5,"adventure":4,"travel":4,"physical":3,"learning":5,"creative":1,"social":3,"relationships":1,"courage":3,"freedom":3,"meaning":3,"budget":3,"time":2,"physical_level":3,"planning":3,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":true,"top2":false,"stretch":true,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ОТКРЫТЬ НОВЫЙ МИР"},{"id":"IDEA_010","title_ru":"Подготовиться к восхождению и покорить вершину","description_ru":"Выбрать вершину, к которой нельзя отправиться без подготовки, и пройти весь путь — от первых тренировок до момента на вершине.","first_step_ru":"Найди вершину, которая станет для тебя настоящим вызовом, но останется достижимой, и узнай, какая подготовка для неё нужна.","category":"Physical","experience_type":"sport_adventure","impact":5,"accessibility":2,"novelty":5,"adventure":5,"travel":4,"physical":5,"learning":4,"creative":1,"social":2,"relationships":1,"courage":5,"freedom":4,"meaning":3,"budget":4,"time":4,"physical_level":4,"planning":4,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":true,"top2":false,"stretch":true,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ПОСТАВИТЬ СЕБЕ ФИЗИЧЕСКУЮ ЦЕЛЬ"},{"id":"IDEA_011","title_ru":"Пройти многодневный маршрут пешком","description_ru":"Провести несколько дней в пути, где каждый день начинается с одной простой цели — идти дальше и увидеть, куда приведёт маршрут.","first_step_ru":"Выбери маршрут на 2–4 дня, который тебе действительно хочется пройти, и узнай его сложность, лучший сезон и что понадобится для подготовки.","category":"Physical","experience_type":"sport_adventure","impact":5,"accessibility":2,"novelty":5,"adventure":5,"travel":5,"physical":5,"learning":3,"creative":1,"social":2,"relationships":2,"courage":4,"freedom":4,"meaning":2,"budget":3,"time":4,"physical_level":3,"planning":3,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":true,"top2":false,"stretch":true,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ПРОВЕРИТЬ СЕБЯ ДИСТАНЦИЕЙ"},{"id":"IDEA_013","title_ru":"Прыгнуть с парашютом","description_ru":"Сделать шаг навстречу одному из самых сильных страхов — и испытать момент свободного падения хотя бы раз в жизни.","first_step_ru":"Найди сертифицированный дропзон, где можно прыгнуть в тандеме с инструктором, и посмотри ближайшие даты и условия для первого прыжка.","category":"Courage","experience_type":"sport_adventure","impact":5,"accessibility":2,"novelty":5,"adventure":5,"travel":2,"physical":3,"learning":1,"creative":0,"social":1,"relationships":1,"courage":5,"freedom":3,"meaning":3,"budget":1,"time":3,"physical_level":3,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":true,"top2":false,"stretch":true,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"СДЕЛАТЬ ОДИН БОЛЬШОЙ ШАГ"},{"id":"IDEA_014","title_ru":"Научиться одному навыку по-настоящему","description_ru":"Не просто попробовать что-то новое, а пройти этап «у меня ничего не получается» и дойти до момента, когда ты уверенно можешь сказать: «Я это умею».","first_step_ru":"Выбери один навык, который давно хочется освоить, и посвяти ему минимум 20 часов практики. Первое занятие запланируй уже сейчас.","category":"Skills","experience_type":"mastery_skill","impact":4,"accessibility":3,"novelty":3,"adventure":2,"travel":1,"physical":2,"learning":5,"creative":3,"social":2,"relationships":1,"courage":3,"freedom":3,"meaning":2,"budget":4,"time":2,"physical_level":3,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"УЙТИ В ГЛУБИНУ"},{"id":"IDEA_015","title_ru":"Выучить язык до уровня живого общения","description_ru":"Дойти до момента, когда ты можешь провести целый вечер, общаясь на другом языке без переводчика и постоянного перехода на родной.","first_step_ru":"Выбери язык и начни заниматься с конкретной целью — провести первый вечер полностью на нём. Для старта запланируй разговорный урок, где будешь говорить с первого занятия.","category":"Skills","experience_type":"mastery_skill","impact":5,"accessibility":3,"novelty":3,"adventure":2,"travel":3,"physical":0,"learning":5,"creative":3,"social":5,"relationships":2,"courage":3,"freedom":4,"meaning":2,"budget":4,"time":1,"physical_level":3,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":true,"top2":false,"stretch":false,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ДОВЕСТИ НАВЫК ДО ЖИВОГО РЕЗУЛЬТАТА"},{"id":"IDEA_016","title_ru":"Научиться играть любимую песню на музыкальном инструменте","description_ru":"Не ставить цель стать музыкантом, а однажды самому исполнить песню, которую раньше ты мог только слушать.","first_step_ru":"Выбери песню и инструмент, на котором хочешь её сыграть, и найди урок или разбор именно этой композиции.","category":"Creative","experience_type":"mastery_skill","impact":4,"accessibility":3,"novelty":3,"adventure":1,"travel":0,"physical":0,"learning":5,"creative":5,"social":2,"relationships":2,"courage":3,"freedom":3,"meaning":1,"budget":3,"time":1,"physical_level":2,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"НАУЧИТЬСЯ ТОМУ, ЧТО ДАВНО НРАВИТСЯ"},{"id":"IDEA_017","title_ru":"Создать что-то своими руками с нуля","description_ru":"Не просто сходить на мастер-класс, а создать что-то настоящее и полезное: кружку, украшение, предмет мебели, сумку или что-то для дома.","first_step_ru":"Выбери вещь, которую тебе действительно хочется сделать, и найди мастерскую, курс или понятную инструкцию, с которой можно начать.","category":"Creative","experience_type":"mastery_skill","impact":4,"accessibility":3,"novelty":3,"adventure":1,"travel":0,"physical":2,"learning":5,"creative":5,"social":2,"relationships":1,"courage":2,"freedom":4,"meaning":2,"budget":3,"time":2,"physical_level":3,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"СОЗДАТЬ ЧТО-ТО РУКАМИ"},{"id":"IDEA_018","title_ru":"Снять короткий фильм о своей жизни сейчас","description_ru":"Сохранить этот период жизни таким, какой он есть: твой голос, близких людей, привычные места, маленькие ритуалы и обычные дни.","first_step_ru":"В течение недели снимай короткие моменты из своей обычной жизни, а потом собери их в фильм на 3–5 минут.","category":"Creative","experience_type":"creative_project","impact":4,"accessibility":3,"novelty":4,"adventure":2,"travel":1,"physical":0,"learning":3,"creative":5,"social":3,"relationships":5,"courage":3,"freedom":4,"meaning":1,"budget":3,"time":1,"physical_level":3,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"СОХРАНИТЬ ЭТОТ ПЕРИОД ЖИЗНИ"},{"id":"IDEA_019","title_ru":"Написать историю и довести её до конца","description_ru":"Превратить идею, которая живёт только в голове, в законченную историю — пусть небольшую и неидеальную, но свою.","first_step_ru":"Реши, какую историю хочешь рассказать, задай ей небольшой объём и напиши первые 500 слов. Главная цель — дойти до последней точки.","category":"Create","experience_type":"creative_project","impact":4,"accessibility":3,"novelty":4,"adventure":1,"travel":0,"physical":0,"learning":4,"creative":5,"social":1,"relationships":1,"courage":4,"freedom":4,"meaning":1,"budget":4,"time":1,"physical_level":3,"planning":2,"solo":true,"with_people":false,"travel_required":false,"active":true,"top1":true,"top2":false,"stretch":false,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ДОВЕСТИ ИДЕЮ ДО КОНЦА"},{"id":"IDEA_020","title_ru":"Создать свою фотосерию","description_ru":"Выбрать одну тему и попробовать рассказать историю только через фотографии — людей, места, детали или моменты, которые обычно остаются незамеченными.","first_step_ru":"Выбери тему, которую тебе интересно замечать вокруг себя, и поставь цель сделать 10 фотографий. Первые три сними в ближайшие два дня.","category":"Creative","experience_type":"creative_project","impact":4,"accessibility":3,"novelty":4,"adventure":2,"travel":2,"physical":1,"learning":4,"creative":5,"social":2,"relationships":2,"courage":2,"freedom":3,"meaning":1,"budget":3,"time":1,"physical_level":2,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"СДЕЛАТЬ ТВОРЧЕСКИЙ ПРОЕКТ"},{"id":"IDEA_021","title_ru":"Сходить на курс импровизации","description_ru":"Попробовать действовать без сценария, быстрее реагировать и меньше переживать о том, как ты выглядишь со стороны.","first_step_ru":"Найди открытый урок или занятие для новичков и запишись на первое — без обязательства продолжать курс.","category":"Courage","experience_type":"courage_challenge","impact":4,"accessibility":4,"novelty":5,"adventure":3,"travel":0,"physical":1,"learning":4,"creative":5,"social":5,"relationships":1,"courage":5,"freedom":4,"meaning":2,"budget":2,"time":1,"physical_level":2,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":true,"list_only":false,"editorial_note":"Может быть №3 — конкретный более смелый опыт.","angle_ru":"ВЫЙТИ ИЗ ПРИВЫЧНОЙ РОЛИ"},{"id":"IDEA_022","title_ru":"Научиться танцу, который всегда нравился","description_ru":"Перестать только смотреть на других и наконец самому попробовать танец, который давно тебя цепляет.","first_step_ru":"Выбери конкретный стиль — сальсу, бачату, танго, хип-хоп или любой другой — и запишись на первое занятие для новичков.","category":"Skills","experience_type":"mastery_skill","impact":4,"accessibility":3,"novelty":3,"adventure":2,"travel":0,"physical":4,"learning":5,"creative":4,"social":5,"relationships":1,"courage":4,"freedom":3,"meaning":2,"budget":4,"time":3,"physical_level":2,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"НАУЧИТЬСЯ ДВИГАТЬСЯ ИНАЧЕ"},{"id":"IDEA_023","title_ru":"Запустить свой проект за 30 дней","description_ru":"Сделать что-то своё достаточно маленьким, чтобы закончить, а не годами готовить.","first_step_ru":"Сформулируй проект одной фразой и определи, что должно существовать через 30 дней, чтобы считать его запущенным.","category":"Create","experience_type":"creative_project","impact":5,"accessibility":3,"novelty":4,"adventure":3,"travel":0,"physical":0,"learning":5,"creative":5,"social":3,"relationships":1,"courage":4,"freedom":5,"meaning":2,"budget":3,"time":1,"physical_level":3,"planning":3,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":true,"top2":false,"stretch":true,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"СОЗДАТЬ ЧТО-ТО СВОЁ"},{"id":"IDEA_024","title_ru":"Продать первую вещь, созданную тобой","description_ru":"Превратить идею в что-то реальное — не ждать идеального момента и не готовиться бесконечно, а создать первую работающую версию за месяц.","first_step_ru":"Опиши идею одним предложением и реши, что конкретно должно быть готово через 30 дней. Затем выбери одно действие, которое можешь сделать уже сегодня.","category":"Create","experience_type":"creative_project","impact":4,"accessibility":3,"novelty":4,"adventure":3,"travel":0,"physical":0,"learning":4,"creative":5,"social":3,"relationships":1,"courage":5,"freedom":5,"meaning":2,"budget":3,"time":1,"physical_level":3,"planning":3,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":true,"top2":false,"stretch":true,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ПРОВЕРИТЬ СЕБЯ В ДЕЛЕ"},{"id":"IDEA_025","title_ru":"Опубликовать свою работу под своим именем","description_ru":"Перестать прятать то, что ты создаёшь, в заметках и черновиках — и однажды показать это другим. Это может быть статья, рассказ, фотография, исследование, музыка или любой другой результат твоей работы.","first_step_ru":"Выбери одну законченную работу, которой готов поделиться, и назначь конкретную дату и место публикации.","category":"Create","experience_type":"creative_project","impact":4,"accessibility":3,"novelty":4,"adventure":2,"travel":0,"physical":0,"learning":4,"creative":5,"social":3,"relationships":1,"courage":5,"freedom":4,"meaning":1,"budget":3,"time":1,"physical_level":2,"planning":2,"solo":true,"with_people":false,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"ПОКАЗАТЬ СВОЮ РАБОТУ МИРУ"},{"id":"IDEA_026","title_ru":"Провести свой первый мастер-класс","description_ru":"Выбрать то, что у тебя хорошо получается, и впервые поделиться этим с другими — своим опытом, знаниями или навыком.","first_step_ru":"Выбери тему, которую можешь интересно раскрыть за 30–60 минут, и пригласи 3–5 человек на свой первый небольшой мастер-класс.","category":"Create","experience_type":"creative_project","impact":4,"accessibility":3,"novelty":4,"adventure":3,"travel":0,"physical":1,"learning":4,"creative":4,"social":5,"relationships":2,"courage":5,"freedom":4,"meaning":1,"budget":2,"time":1,"physical_level":3,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"ПЕРЕДАТЬ ТО, ЧТО УМЕЕШЬ"},{"id":"IDEA_027","title_ru":"Собрать людей вокруг своей идеи","description_ru":"Не искать готовый круг единомышленников, а самому создать повод для людей объединиться — вокруг интереса, идеи, хобби или общей цели.","first_step_ru":"Придумай, вокруг чего тебе хотелось бы собрать людей, и пригласи первых 3–5 человек на встречу, совместное занятие или небольшой проект.","category":"Social","experience_type":"creative_project","impact":4,"accessibility":3,"novelty":4,"adventure":3,"travel":0,"physical":1,"learning":3,"creative":5,"social":5,"relationships":2,"courage":5,"freedom":4,"meaning":2,"budget":3,"time":1,"physical_level":4,"planning":3,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":true,"top2":false,"stretch":false,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"СОБРАТЬ ЛЮДЕЙ ВОКРУГ ИДЕИ"},{"id":"IDEA_028","title_ru":"Устроить большой ужин для близких","description_ru":"Собрать за одним столом людей, с которыми тебе хочется проводить больше времени, вместо очередного «надо обязательно как-нибудь встретиться».","first_step_ru":"Составь список тех, кого хочется видеть за этим столом, выбери две возможные даты и отправь приглашения.","category":"Social","experience_type":"relationships","impact":4,"accessibility":4,"novelty":3,"adventure":1,"travel":0,"physical":0,"learning":1,"creative":4,"social":5,"relationships":5,"courage":2,"freedom":3,"meaning":2,"budget":1,"time":1,"physical_level":3,"planning":2,"solo":false,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"СОЗДАТЬ ОБЩЕЕ ВОСПОМИНАНИЕ"},{"id":"IDEA_029","title_ru":"Отправиться в путешествие с мамой или папой","description_ru":"Провести несколько дней вместе в новой обстановке и создать общее воспоминание, которое останется с вами надолго.","first_step_ru":"Обсудите, куда вам обоим хотелось бы съездить на 2–3 дня, выберите три варианта и найдите подходящие даты.","category":"Relationships","experience_type":"relationships","impact":5,"accessibility":4,"novelty":3,"adventure":3,"travel":4,"physical":1,"learning":1,"creative":1,"social":3,"relationships":5,"courage":2,"freedom":4,"meaning":3,"budget":3,"time":1,"physical_level":3,"planning":2,"solo":false,"with_people":true,"travel_required":true,"active":true,"top1":true,"top2":false,"stretch":false,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"СДЕЛАТЬ ЧТО-ТО ВАЖНОЕ ВМЕСТЕ"},{"id":"IDEA_030","title_ru":"Записать истории своих родителей","description_ru":"Узнать и сохранить их истории — о детстве, молодости, любви, мечтах, важных решениях и жизни до твоего появления.","first_step_ru":"Подготовь 10 вопросов о том, о чём вы раньше почти не говорили, и договорись о первом разговоре.","category":"Relationships","experience_type":"relationships","impact":5,"accessibility":4,"novelty":3,"adventure":0,"travel":0,"physical":0,"learning":2,"creative":3,"social":4,"relationships":5,"courage":3,"freedom":5,"meaning":1,"budget":2,"time":1,"physical_level":3,"planning":2,"solo":false,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"СОХРАНИТЬ СЕМЕЙНУЮ ИСТОРИЮ"},{"id":"IDEA_031","title_ru":"Восстановить связь с человеком, которого тебе не хватает","description_ru":"Вернуть в свою жизнь человека, с которым вы когда-то были близки, но со временем потеряли связь.","first_step_ru":"Подумай, с кем тебе действительно хотелось бы снова общаться, и напиши простое сообщение без долгих объяснений: «Я недавно о тебе вспоминал(а). Как ты?»","category":"Relationships","experience_type":"relationships","impact":4,"accessibility":5,"novelty":3,"adventure":1,"travel":1,"physical":0,"learning":1,"creative":1,"social":4,"relationships":5,"courage":4,"freedom":4,"meaning":1,"budget":1,"time":1,"physical_level":1,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"ВЕРНУТЬ ВАЖНОГО ЧЕЛОВЕКА В ЖИЗНЬ"},{"id":"IDEA_032","title_ru":"Сказать то, что давно остаётся несказанным","description_ru":"Не оставлять важные слова на потом — будь то благодарность, признание, извинение или то, что давно хочется сказать вслух.","first_step_ru":"Реши, с кем тебе нужен этот разговор, и что самое главное ты хочешь сказать. Не жди идеального момента — выбери день и начни разговор.","category":"Courage","experience_type":"relationships","impact":4,"accessibility":5,"novelty":3,"adventure":0,"travel":0,"physical":0,"learning":1,"creative":1,"social":4,"relationships":5,"courage":5,"freedom":5,"meaning":1,"budget":1,"time":1,"physical_level":1,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":true,"list_only":false,"editorial_note":"Может быть №3 — конкретный более смелый опыт.","angle_ru":"СКАЗАТЬ ТО, ЧТО ДАВНО НЕ СКАЗАНО"},{"id":"IDEA_033","title_ru":"Провести день с близким человеком без телефонов","description_ru":"На один день убрать экраны и провести время по-настоящему вместе — без уведомлений, соцсетей и постоянных отвлечений.","first_step_ru":"Выберите день, придумайте, как хотите его провести, и заранее договоритесь убрать телефоны до вечера.","category":"Relationships","experience_type":"relationships","impact":4,"accessibility":4,"novelty":3,"adventure":1,"travel":1,"physical":1,"learning":0,"creative":2,"social":3,"relationships":5,"courage":2,"freedom":4,"meaning":1,"budget":1,"time":1,"physical_level":1,"planning":1,"solo":false,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"БОЛЬШЕ НАСТОЯЩЕГО ПРИСУТСТВИЯ"},{"id":"IDEA_034","title_ru":"Не отказываться от планов из-за отсутствия компании","description_ru":"Перестать откладывать то, что тебе хочется, только потому, что никто не может или не хочет пойти вместе.","first_step_ru":"Выбери концерт, выставку, мероприятие или место, куда давно хочется попасть, и купи билет для себя.","category":"Freedom","experience_type":"freedom_reset","impact":3,"accessibility":5,"novelty":3,"adventure":3,"travel":2,"physical":1,"learning":1,"creative":1,"social":2,"relationships":1,"courage":5,"freedom":5,"meaning":2,"budget":1,"time":1,"physical_level":1,"planning":1,"solo":true,"with_people":false,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"НЕ ЖДАТЬ КОМПАНИЮ"},{"id":"IDEA_035","title_ru":"Сходить на событие, где ты никого не знаешь","description_ru":"Оказаться среди совершенно новых людей, завести разговор и дать себе шанс на неожиданное знакомство.","first_step_ru":"Найди небольшое событие по интересам — встречу, лекцию, клуб, воркшоп или вечеринку — и зарегистрируйся, даже если идти туда не с кем.","category":"Social","experience_type":"courage_challenge","impact":4,"accessibility":4,"novelty":5,"adventure":3,"travel":1,"physical":1,"learning":2,"creative":2,"social":5,"relationships":1,"courage":5,"freedom":4,"meaning":2,"budget":2,"time":1,"physical_level":2,"planning":1,"solo":true,"with_people":false,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":true,"list_only":false,"editorial_note":"Может быть №3 — конкретный более смелый опыт.","angle_ru":"ОКАЗАТЬСЯ СРЕДИ НОВЫХ ЛЮДЕЙ"},{"id":"IDEA_036","title_ru":"Выступить перед живой аудиторией","description_ru":"Выйти перед людьми и впервые почувствовать, каково это — когда внимание аудитории направлено на тебя и то, что ты хочешь сказать или показать.","first_step_ru":"Выбери формат, который тебе ближе: open mic, короткий доклад, презентацию, выступление или чтение — и найди возможность сделать это вживую.","category":"Courage","experience_type":"courage_challenge","impact":5,"accessibility":4,"novelty":5,"adventure":3,"travel":0,"physical":1,"learning":3,"creative":4,"social":5,"relationships":1,"courage":5,"freedom":3,"meaning":1,"budget":2,"time":1,"physical_level":2,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":true,"top2":false,"stretch":true,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"СТАТЬ ВИДИМЕЕ"},{"id":"IDEA_037","title_ru":"Попробовать что-то совершенно новое","description_ru":"Выбрать занятие, в котором у тебя нет никакого опыта, и снова почувствовать себя новичком — без необходимости сразу делать всё хорошо.","first_step_ru":"Найди то, чего ты никогда раньше не пробовал(а), и запишись на одно первое занятие просто ради нового опыта.","category":"Courage","experience_type":"courage_challenge","impact":4,"accessibility":4,"novelty":5,"adventure":4,"travel":1,"physical":2,"learning":5,"creative":3,"social":3,"relationships":1,"courage":5,"freedom":4,"meaning":1,"budget":3,"time":2,"physical_level":2,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"РАЗРЕШИТЬ СЕБЕ БЫТЬ НОВИЧКОМ"},{"id":"IDEA_038","title_ru":"Провести 24 часа без интернета","description_ru":"На один день отключиться от соцсетей, новостей, сообщений и бесконечного скролла — и посмотреть, чем заполнится время без привычного онлайна.","first_step_ru":"Выбери день, когда можешь позволить себе быть офлайн, предупреди близких и заранее придумай несколько вещей, которыми хочется заняться без интернета.","category":"Freedom","experience_type":"digital_reset","impact":3,"accessibility":5,"novelty":3,"adventure":2,"travel":0,"physical":0,"learning":1,"creative":2,"social":1,"relationships":2,"courage":3,"freedom":5,"meaning":1,"budget":1,"time":1,"physical_level":1,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"ВЕРНУТЬ СЕБЕ ВНИМАНИЕ"},{"id":"IDEA_039","title_ru":"Устроить себе полностью свободный день","description_ru":"Провести целый день без планов, обязательств и чувства, что нужно обязательно сделать что-то полезное.","first_step_ru":"Выбери день, освободи его от работы, встреч и дел — и специально ничего не планируй заранее.","category":"Freedom","experience_type":"freedom_reset","impact":3,"accessibility":5,"novelty":3,"adventure":2,"travel":0,"physical":1,"learning":1,"creative":2,"social":1,"relationships":1,"courage":2,"freedom":5,"meaning":1,"budget":1,"time":1,"physical_level":1,"planning":1,"solo":true,"with_people":false,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"ОСВОБОДИТЬ МЕСТО ДЛЯ СЕБЯ"},{"id":"IDEA_040","title_ru":"На неделю сменить привычную обстановку","description_ru":"Продолжать жить своей обычной жизнью — работать, заниматься привычными делами — но из совершенно другого места и посмотреть, как это меняет твой ритм и ощущения.","first_step_ru":"Выбери место, где тебе было бы интересно провести обычную неделю, и посмотри варианты жилья с удобными условиями для твоей повседневной жизни.","category":"Freedom","experience_type":"travel","impact":5,"accessibility":2,"novelty":5,"adventure":3,"travel":3,"physical":1,"learning":2,"creative":2,"social":2,"relationships":1,"courage":3,"freedom":5,"meaning":2,"budget":2,"time":1,"physical_level":2,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":true,"top2":false,"stretch":false,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ПОСМОТРЕТЬ НА ЖИЗНЬ СО СТОРОНЫ"},{"id":"IDEA_041","title_ru":"Заканчивать работу вовремя целую неделю","description_ru":"На неделю вернуть работе чёткие границы и увидеть, сколько жизни остаётся, когда рабочий день действительно заканчивается.","first_step_ru":"Выбери время, после которого работа на этой неделе заканчивается, и каждый день закрывай ноутбук в этот момент — даже если список задач ещё не пуст.","category":"Freedom","experience_type":"freedom_reset","impact":3,"accessibility":5,"novelty":3,"adventure":1,"travel":0,"physical":0,"learning":1,"creative":1,"social":2,"relationships":3,"courage":3,"freedom":5,"meaning":1,"budget":2,"time":1,"physical_level":1,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"ВЕРНУТЬ СЕБЕ ВЕЧЕРА"},{"id":"IDEA_042","title_ru":"Каждый день пробовать что-то новое в течение месяца","description_ru":"Добавить больше новизны в обычную жизнь, не дожидаясь отпуска, большого путешествия или особого повода.","first_step_ru":"Составь список из 30 небольших вещей, которых ещё не было в твоей обычной жизни, — новое блюдо, маршрут, место, занятие или знакомство — и начни с первой.","category":"Adventure","experience_type":"micro_adventure","impact":3,"accessibility":5,"novelty":4,"adventure":4,"travel":1,"physical":2,"learning":4,"creative":4,"social":3,"relationships":2,"courage":4,"freedom":4,"meaning":2,"budget":3,"time":2,"physical_level":2,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"ДОБАВИТЬ НОВИЗНУ В ОБЫЧНУЮ ЖИЗНЬ"},{"id":"IDEA_043","title_ru":"Провести ночь под открытым небом","description_ru":"Заснуть под звёздами и проснуться с рассветом — хотя бы раз провести ночь, когда между тобой и небом нет крыши.","first_step_ru":"Найди безопасное место, где можно легально остаться на ночь под открытым небом, и проверь погоду и минимальное необходимое снаряжение.","category":"Adventure","experience_type":"nature_adventure","impact":5,"accessibility":3,"novelty":5,"adventure":4,"travel":2,"physical":2,"learning":2,"creative":1,"social":2,"relationships":2,"courage":4,"freedom":4,"meaning":1,"budget":2,"time":2,"physical_level":2,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"ВЕРНУТЬСЯ БЛИЖЕ К ПРИРОДЕ"},{"id":"IDEA_044","title_ru":"Попросить то, чего тебе действительно хочется","description_ru":"Не отказываться от своих желаний заранее только из-за страха услышать «нет» — будь то повышение, помощь, возможность, приглашение или что-то личное.","first_step_ru":"Подумай, о чём тебе давно хочется попросить, но останавливает возможный отказ. Сформулируй просьбу и озвучь её тому, кто действительно может сказать «да».","category":"Courage","experience_type":"courage_challenge","impact":4,"accessibility":5,"novelty":5,"adventure":2,"travel":0,"physical":0,"learning":2,"creative":1,"social":3,"relationships":2,"courage":5,"freedom":5,"meaning":1,"budget":1,"time":1,"physical_level":1,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"ПОПРОСИТЬ О БОЛЬШЕМ"},{"id":"IDEA_045","title_ru":"Стать волонтёром в деле, которое тебе действительно важно","description_ru":"Не просто поддерживать то, во что ты веришь, со стороны, а лично вложить своё время и силы в помощь людям, животным, природе или другой важной для тебя сфере.","first_step_ru":"Выбери направление, которое тебе действительно небезразлично, и найди возможность поучаствовать хотя бы один раз — например, в акции, мероприятии или конкретной волонтёрской задаче.","category":"Meaning","experience_type":"meaning_contribution","impact":4,"accessibility":3,"novelty":3,"adventure":2,"travel":1,"physical":2,"learning":3,"creative":2,"social":5,"relationships":2,"courage":3,"freedom":4,"meaning":1,"budget":2,"time":2,"physical_level":3,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":true,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ДОБАВИТЬ БОЛЬШЕ СМЫСЛА"},{"id":"IDEA_046","title_ru":"Научить кого-то тому, что ты хорошо умеешь","description_ru":"Использовать свой опыт не только для себя, а помочь другому человеку освоить навык, который может открыть для него новые возможности.","first_step_ru":"Подумай, чему ты можешь научить другого человека — от профессионального навыка до спорта, языка или творчества — и предложи провести несколько занятий бесплатно.","category":"Meaning","experience_type":"meaning_contribution","impact":4,"accessibility":3,"novelty":3,"adventure":1,"travel":0,"physical":0,"learning":3,"creative":2,"social":4,"relationships":3,"courage":2,"freedom":5,"meaning":1,"budget":3,"time":1,"physical_level":2,"planning":1,"solo":false,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"СДЕЛАТЬ СВОЙ ОПЫТ ПОЛЕЗНЫМ"},{"id":"IDEA_047","title_ru":"Сохранить историю своей семьи","description_ru":"Собрать фотографии, воспоминания и семейные истории, которые иначе со временем могут потеряться, и сохранить их для следующих поколений.","first_step_ru":"Начни с 10 фотографий и 5 историй, которые особенно важно сохранить. Запиши, кто на снимках, где и когда они сделаны и что за ними стоит.","category":"Meaning","experience_type":"relationships","impact":4,"accessibility":4,"novelty":3,"adventure":0,"travel":0,"physical":0,"learning":3,"creative":5,"social":3,"relationships":5,"courage":2,"freedom":5,"meaning":1,"budget":4,"time":1,"physical_level":4,"planning":3,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":true,"top2":false,"stretch":false,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ОСТАВИТЬ ЧТО-ТО ПОСЛЕ СЕБЯ"},{"id":"IDEA_048","title_ru":"Побывать на большом культурном празднике","description_ru":"Увидеть место в момент, когда его традиции оживают по-настоящему — на карнавале, фестивале, национальном празднике или многовековой церемонии.","first_step_ru":"Выбери событие, которое тебе действительно хочется увидеть вживую, узнай дату следующего проведения и начни планировать поездку вокруг него.","category":"Experience","experience_type":"travel","impact":5,"accessibility":2,"novelty":5,"adventure":4,"travel":5,"physical":2,"learning":3,"creative":3,"social":5,"relationships":2,"courage":3,"freedom":4,"meaning":3,"budget":3,"time":2,"physical_level":4,"planning":3,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":true,"top2":false,"stretch":true,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ОКАЗАТЬСЯ ВНУТРИ ДРУГОЙ КУЛЬТУРЫ"},{"id":"IDEA_049","title_ru":"Отправиться в путешествие ради концерта или события","description_ru":"Не ждать, пока любимый артист, фестиваль или событие окажутся рядом, а самому поехать туда, где это происходит.","first_step_ru":"Выбери событие, которое тебе действительно хочется увидеть вживую, посмотри даты и посчитай бюджет поездки вместе с билетами.","category":"Experience","experience_type":"travel","impact":5,"accessibility":2,"novelty":5,"adventure":3,"travel":4,"physical":1,"learning":0,"creative":2,"social":4,"relationships":2,"courage":3,"freedom":3,"meaning":3,"budget":2,"time":1,"physical_level":3,"planning":2,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":true,"top2":false,"stretch":false,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ПОЕХАТЬ РАДИ ТОГО, ЧТО ЛЮБИШЬ"},{"id":"IDEA_050","title_ru":"Создать традицию, которая останется с тобой на годы","description_ru":"Придумать что-то своё, к чему захочется возвращаться снова и снова — каждый год, сезон или в особенный день.","first_step_ru":"Реши, что тебе хотелось бы превратить в традицию: ежегодную поездку, ужин с друзьями, семейный день или личный ритуал — и назначь первый раз.","category":"Relationships","experience_type":"relationships","impact":4,"accessibility":4,"novelty":3,"adventure":1,"travel":1,"physical":1,"learning":1,"creative":3,"social":5,"relationships":5,"courage":2,"freedom":4,"meaning":2,"budget":3,"time":1,"physical_level":3,"planning":2,"solo":false,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"СОЗДАТЬ СВОЮ ТРАДИЦИЮ"},{"id":"IDEA_051","title_ru":"Научиться кайтсерфингу","description_ru":"Научиться уверенно управлять кайтом, вставать на доску и впервые почувствовать свободу движения по воде с помощью ветра.","first_step_ru":"Найди кайт-школу с сертифицированными инструкторами и запишись на первый урок — обучение начинается с управления кайтом и безопасности, а не с доски.","category":"Physical","experience_type":"sport_adventure","impact":5,"accessibility":2,"novelty":5,"adventure":5,"travel":4,"physical":5,"learning":5,"creative":1,"social":3,"relationships":1,"courage":4,"freedom":5,"meaning":3,"budget":3,"time":3,"physical_level":4,"planning":3,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":true,"top2":false,"stretch":true,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ОСВОИТЬ СПОРТ СО СВОБОДОЙ"},{"id":"IDEA_052","title_ru":"Полетать на параплане","description_ru":"Оторваться от земли и увидеть горы, море или город с высоты — без стекла самолёта между тобой и пейзажем.","first_step_ru":"Выбери место, над которым тебе особенно хотелось бы полетать, и найди тандемный полёт с сертифицированным пилотом.","category":"Adventure","experience_type":"sport_adventure","impact":5,"accessibility":2,"novelty":5,"adventure":5,"travel":4,"physical":2,"learning":2,"creative":1,"social":2,"relationships":1,"courage":5,"freedom":4,"meaning":3,"budget":3,"time":2,"physical_level":3,"planning":2,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":true,"top2":false,"stretch":true,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ПОСМОТРЕТЬ НА МИР СВЕРХУ"},{"id":"IDEA_053","title_ru":"Устроить гастрономический день","description_ru":"Посвятить целый день новым вкусам — пробовать местные блюда, заходить в необычные места и выбирать еду, которую обычно ты бы не заказал.","first_step_ru":"Выбери город или район, который интересно исследовать через еду, и составь маршрут из 3–5 точек: от местного рынка и стритфуда до места для особенного ужина.","category":"Experience","experience_type":"food_culture","impact":3,"accessibility":5,"novelty":3,"adventure":3,"travel":2,"physical":0,"learning":1,"creative":2,"social":4,"relationships":3,"courage":2,"freedom":3,"meaning":3,"budget":2,"time":2,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"ИССЛЕДОВАТЬ МЕСТО ЧЕРЕЗ ВКУС"},{"id":"IDEA_054","title_ru":"Сходить в хороший ресторан без компании","description_ru":"Не ждать особого повода или подходящей компании, чтобы устроить себе красивый вечер и получить удовольствие от него самостоятельно.","first_step_ru":"Выбери ресторан, в который давно хочется попасть, забронируй стол на одного и преврати этот ужин в отдельное событие.","category":"Freedom","experience_type":"food_culture","impact":3,"accessibility":5,"novelty":3,"adventure":2,"travel":2,"physical":0,"learning":1,"creative":1,"social":1,"relationships":1,"courage":4,"freedom":5,"meaning":2,"budget":3,"time":1,"physical_level":1,"planning":1,"solo":true,"with_people":false,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"РАЗРЕШИТЬ СЕБЕ ХОРОШЕЕ"},{"id":"IDEA_055","title_ru":"Уехать на ретрит на несколько дней","description_ru":"На несколько дней выйти из привычного ритма — меньше работы, экранов и внешнего шума, больше тишины, природы и времени для себя.","first_step_ru":"Выбери формат, который тебе ближе — йога, медитация, digital detox или просто уединённое место на природе — и найди вариант на 2–4 дня.","category":"Wellbeing","experience_type":"digital_reset","impact":3,"accessibility":4,"novelty":3,"adventure":3,"travel":2,"physical":1,"learning":2,"creative":1,"social":2,"relationships":1,"courage":3,"freedom":5,"meaning":4,"budget":3,"time":3,"physical_level":2,"planning":2,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":true,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ВЫКЛЮЧИТЬ ПРИВЫЧНЫЙ ШУМ"},{"id":"IDEA_056","title_ru":"Встретить рассвет в особенном месте","description_ru":"Проснуться до восхода, добраться до красивой точки и увидеть, как начинается новый день — не случайно, а ради самого момента.","first_step_ru":"Выбери место, где тебе особенно хочется увидеть рассвет — у моря, в горах, в пустыне или над городом — и запланируй конкретное утро.","category":"Experience","experience_type":"micro_adventure","impact":3,"accessibility":5,"novelty":4,"adventure":3,"travel":2,"physical":1,"learning":0,"creative":2,"social":2,"relationships":2,"courage":2,"freedom":4,"meaning":2,"budget":1,"time":1,"physical_level":1,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"СДЕЛАТЬ ОБЫЧНЫЙ МОМЕНТ СОБЫТИЕМ"},{"id":"IDEA_057","title_ru":"Провести 48 часов в незнакомом городе","description_ru":"Устроить небольшое приключение без большого отпуска — выбрать новый город и дать себе два дня, чтобы гулять, исследовать и никуда не спешить.","first_step_ru":"Выбери три города, до которых легко добраться, но где тебе ещё не доводилось бывать, и посмотри варианты на ближайшие свободные выходные.","category":"Travel","experience_type":"travel","impact":5,"accessibility":2,"novelty":5,"adventure":4,"travel":5,"physical":1,"learning":1,"creative":1,"social":2,"relationships":1,"courage":3,"freedom":4,"meaning":3,"budget":2,"time":2,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":true,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"БЫСТРО СМЕНИТЬ КАРТИНКУ"},{"id":"IDEA_058","title_ru":"Напечатать фотографии, которые тебе особенно дороги","description_ru":"Не оставлять любимые воспоминания среди тысяч снимков в телефоне, а превратить их во что-то, что можно держать в руках, поставить на полку или повесить на стену.","first_step_ru":"Выбери 20–30 фотографий, которые тебе хочется видеть чаще, и закажи печать — отдельными снимками, фотокнигой или небольшим альбомом.","category":"Relationships","experience_type":"memory_identity","impact":3,"accessibility":5,"novelty":2,"adventure":0,"travel":0,"physical":0,"learning":1,"creative":4,"social":2,"relationships":5,"courage":1,"freedom":2,"meaning":4,"budget":1,"time":1,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"ВЕРНУТЬ ФОТОГРАФИЯМ ФИЗИЧЕСКУЮ ЖИЗНЬ"},{"id":"IDEA_059","title_ru":"Написать бумажное письмо","description_ru":"Выбрать человека, которому хочется сказать что-то важное, и сделать это не сообщением в телефоне, а настоящим письмом, которое можно сохранить.","first_step_ru":"Реши, кому хочется написать — близкому человеку, другу или даже себе в будущем — возьми бумагу и напиши письмо от руки.","category":"Relationships","experience_type":"relationships","impact":4,"accessibility":5,"novelty":3,"adventure":0,"travel":0,"physical":0,"learning":1,"creative":3,"social":2,"relationships":5,"courage":3,"freedom":2,"meaning":5,"budget":1,"time":1,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"СКАЗАТЬ ВАЖНОЕ НЕ В ЧАТЕ"},{"id":"IDEA_060","title_ru":"Устроить себе мини-саббатикал","description_ru":"На несколько дней полностью выйти из рабочего режима — без задач, созвонов и необходимости быть продуктивным — и посвятить это время только тому, чего хочется тебе.","first_step_ru":"Найди в календаре 3–4 дня, которые можно полностью освободить от работы и обязательств, и заранее защити их от новых планов.","category":"Freedom","experience_type":"freedom_reset","impact":3,"accessibility":5,"novelty":3,"adventure":3,"travel":2,"physical":0,"learning":1,"creative":1,"social":1,"relationships":1,"courage":3,"freedom":5,"meaning":4,"budget":2,"time":3,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":true,"top2":false,"stretch":false,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ДАТЬ СЕБЕ БОЛЬШЕ ПРОСТРАНСТВА"},{"id":"IDEA_061","title_ru":"Сходить на концерт незнакомого исполнителя","description_ru":"Выбрать живую музыку без привычных ожиданий и дать себе шанс случайно открыть артиста, которого потом захочется слушать снова.","first_step_ru":"Посмотри афишу небольших концертных площадок и выбери выступление исполнителя, которого ты почти или совсем не знаешь.","category":"Experience","experience_type":"micro_adventure","impact":3,"accessibility":5,"novelty":4,"adventure":4,"travel":1,"physical":1,"learning":1,"creative":3,"social":4,"relationships":1,"courage":3,"freedom":3,"meaning":2,"budget":2,"time":1,"physical_level":1,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"ОТКРЫТЬ НОВУЮ МУЗЫКУ"},{"id":"IDEA_062","title_ru":"Приготовить блюдо ресторанного уровня","description_ru":"Выбрать блюдо, которое обычно ты скорее закажешь в ресторане, и однажды приготовить его дома так, чтобы результат действительно впечатлил тебя.","first_step_ru":"Выбери блюдо, которое давно хочется научиться готовить, найди хороший рецепт или мастер-класс от шефа и запланируй вечер для первой попытки.","category":"Skills","experience_type":"mastery_skill","impact":4,"accessibility":3,"novelty":3,"adventure":0,"travel":0,"physical":1,"learning":4,"creative":4,"social":3,"relationships":2,"courage":2,"freedom":2,"meaning":2,"budget":2,"time":2,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"СДЕЛАТЬ ИЗ ЕДЫ НАВЫК"},{"id":"IDEA_063","title_ru":"Сходить на дегустацию вслепую","description_ru":"Проверить свой вкус без брендов, цен и красивых этикеток — и, возможно, удивиться тому, что тебе действительно нравится.","first_step_ru":"Выбери формат, который тебе интересен — кофе, шоколад, сыр, чай или другие продукты — и найди ближайшую слепую дегустацию.","category":"Food","experience_type":"food_culture","impact":3,"accessibility":4,"novelty":3,"adventure":3,"travel":1,"physical":0,"learning":2,"creative":2,"social":3,"relationships":1,"courage":2,"freedom":3,"meaning":2,"budget":2,"time":1,"physical_level":1,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"ПОПРОБОВАТЬ ВКУС БЕЗ ПОДСКАЗОК"},{"id":"IDEA_064","title_ru":"Устроить вечер кухни незнакомой страны","description_ru":"На один вечер перенестись в другую культуру через еду, музыку и атмосферу — ещё до того, как ты окажешься там в путешествии.","first_step_ru":"Выбери страну, в которой тебе ещё не доводилось бывать, составь меню из 2–3 традиционных блюд и добавь музыку или другие детали для атмосферы.","category":"Social","experience_type":"food_culture","impact":3,"accessibility":4,"novelty":3,"adventure":2,"travel":3,"physical":0,"learning":2,"creative":4,"social":5,"relationships":3,"courage":2,"freedom":3,"meaning":2,"budget":2,"time":1,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"ПУТЕШЕСТВОВАТЬ ЧЕРЕЗ ЕДУ"},{"id":"IDEA_065","title_ru":"Поехать смотреть звёзды","description_ru":"Уехать подальше от городских огней и провести ночь под небом, где действительно видны тысячи звёзд, Млечный Путь и созвездия.","first_step_ru":"Найди место с минимальной световой засветкой, выбери ясную ночь ближе к новолунию и запланируй небольшую поездку специально ради звёзд.","category":"Experience","experience_type":"micro_adventure","impact":3,"accessibility":4,"novelty":4,"adventure":4,"travel":2,"physical":1,"learning":1,"creative":2,"social":2,"relationships":2,"courage":2,"freedom":4,"meaning":3,"budget":1,"time":1,"physical_level":1,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"УЕХАТЬ ТУДА, ГДЕ ТЕМНО"},{"id":"IDEA_066","title_ru":"Сделать путешествие, которое останется только твоим","description_ru":"Провести поездку без мыслей о том, что снять, выложить или показать другим — просто быть там и проживать происходящее для себя.","first_step_ru":"Выбери одну поездку или небольшой выезд и договорись с собой ничего не публиковать во время путешествия — фотографии оставить только для себя.","category":"Freedom","experience_type":"freedom_reset","impact":3,"accessibility":5,"novelty":3,"adventure":3,"travel":3,"physical":0,"learning":1,"creative":1,"social":1,"relationships":2,"courage":3,"freedom":5,"meaning":3,"budget":2,"time":2,"physical_level":1,"planning":1,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"ПРОЖИТЬ ПОЕЗДКУ ТОЛЬКО ДЛЯ СЕБЯ"},{"id":"IDEA_067","title_ru":"Устроить пикник как маленький праздник","description_ru":"Превратить обычный день на природе в событие — выбрать красивое место, собрать любимую еду, позвать близких и никуда не спешить.","first_step_ru":"Выбери место, куда тебе действительно хочется выбраться на пикник, назначь дату и пригласи тех, с кем хочется разделить этот день.","category":"Social","experience_type":"micro_adventure","impact":3,"accessibility":5,"novelty":4,"adventure":2,"travel":1,"physical":1,"learning":1,"creative":4,"social":5,"relationships":4,"courage":1,"freedom":3,"meaning":2,"budget":1,"time":1,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"СДЕЛАТЬ ПРОСТОЙ ДЕНЬ КРАСИВЕЕ"},{"id":"IDEA_068","title_ru":"Устроить день-сюрприз для близкого человека","description_ru":"Придумать целый день вокруг того, что любит другой человек, — с любимыми местами, маленькими сюрпризами и финалом, о котором он не знает заранее.","first_step_ru":"Выбери человека, для которого хочется это сделать, вспомни 3–5 вещей, которые его радуют, и придумай из них сценарий дня.","category":"Relationships","experience_type":"relationships","impact":4,"accessibility":4,"novelty":3,"adventure":3,"travel":1,"physical":1,"learning":2,"creative":4,"social":5,"relationships":5,"courage":3,"freedom":3,"meaning":4,"budget":2,"time":2,"physical_level":1,"planning":3,"solo":false,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"СДЕЛАТЬ ЧТО-ТО ОСОБЕННОЕ ДЛЯ БЛИЗКОГО"},{"id":"IDEA_069","title_ru":"Создать художественный портрет своей жизни сейчас","description_ru":"Сохранить нынешний период не просто фотографией, а через искусство — таким, каким ты захочешь увидеть его спустя много лет.","first_step_ru":"Выбери формат, который тебе ближе: портрет, иллюстрация, фотопроект, скульптура или другой арт-объект — и найди трёх авторов, чей стиль тебе нравится.","category":"Creative","experience_type":"creative_project","impact":4,"accessibility":3,"novelty":4,"adventure":1,"travel":0,"physical":0,"learning":2,"creative":5,"social":2,"relationships":2,"courage":2,"freedom":2,"meaning":4,"budget":2,"time":2,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"ЗАФИКСИРОВАТЬ СЕБЯ СЕЙЧАС"},{"id":"IDEA_070","title_ru":"Сделать первый шаг к новой дружбе","description_ru":"Не ждать, пока новое знакомство само перерастёт во что-то большее, а предложить человеку встретиться ещё раз.","first_step_ru":"Подумай о человеке, с которым тебе было интересно общаться, и предложи встретиться за кофе, на прогулке или за совместным занятием.","category":"Social","experience_type":"relationships","impact":4,"accessibility":5,"novelty":3,"adventure":1,"travel":0,"physical":0,"learning":1,"creative":1,"social":5,"relationships":3,"courage":4,"freedom":3,"meaning":3,"budget":1,"time":1,"physical_level":1,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"СДЕЛАТЬ ПЕРВЫЙ СОЦИАЛЬНЫЙ ШАГ"},{"id":"IDEA_071","title_ru":"Увидеть, как всё устроено изнутри","description_ru":"Попасть туда, куда обычно нет доступа, и своими глазами увидеть, что происходит за кулисами ресторана, театра, аэропорта, производства, фермы или мастерской.","first_step_ru":"Выбери место или профессию, устройство которых тебе всегда было интересно, и найди экскурсию, день открытых дверей или возможность попасть туда с кем-то изнутри.","category":"Learning","experience_type":"mastery_skill","impact":4,"accessibility":3,"novelty":3,"adventure":3,"travel":1,"physical":1,"learning":4,"creative":2,"social":4,"relationships":1,"courage":3,"freedom":3,"meaning":3,"budget":2,"time":1,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"УВИДЕТЬ, КАК ВСЁ УСТРОЕНО"},{"id":"IDEA_072","title_ru":"Научиться печь свой идеальный хлеб","description_ru":"Освоить рецепт настолько хорошо, чтобы запах свежего хлеба дома перестал быть редким экспериментом и стал твоим маленьким ритуалом.","first_step_ru":"Выбери хлеб, который тебе действительно нравится — на закваске, фокаччу, багет или другой — и испеки его первый раз.","category":"Skills","experience_type":"mastery_skill","impact":4,"accessibility":3,"novelty":3,"adventure":0,"travel":0,"physical":1,"learning":4,"creative":3,"social":2,"relationships":2,"courage":1,"freedom":2,"meaning":2,"budget":1,"time":2,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"ОСВОИТЬ ПРОСТОЙ РИТУАЛ"},{"id":"IDEA_073","title_ru":"Устроить себе отпуск посреди недели","description_ru":"На один обычный будний день выйти из привычного сценария — никуда не спешить, красиво позавтракать, отправиться в новое место и делать только то, что хочется.","first_step_ru":"Выбери будний день в ближайший месяц, полностью освободи его от работы и заранее придумай только одну вещь, которую тебе особенно хочется сделать.","category":"Freedom","experience_type":"freedom_reset","impact":3,"accessibility":5,"novelty":3,"adventure":2,"travel":1,"physical":0,"learning":0,"creative":1,"social":2,"relationships":1,"courage":3,"freedom":5,"meaning":3,"budget":2,"time":1,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"ВЕРНУТЬ СЕБЕ БУДНИ"},{"id":"IDEA_074","title_ru":"Отправиться в волонтёрское путешествие","description_ru":"Поехать в новое место не только ради впечатлений, а чтобы на несколько дней или недель стать частью проекта, которому действительно нужна помощь.","first_step_ru":"Выбери направление, которое тебе близко — природа, животные, образование, социальные проекты — и найди три проверенные программы, куда можно присоединиться на короткий срок.","category":"Meaning","experience_type":"meaning_contribution","impact":5,"accessibility":3,"novelty":3,"adventure":4,"travel":4,"physical":2,"learning":3,"creative":1,"social":5,"relationships":2,"courage":4,"freedom":3,"meaning":5,"budget":2,"time":3,"physical_level":2,"planning":3,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":true,"top2":true,"stretch":true,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"СОВМЕСТИТЬ ПУТЕШЕСТВИЕ И СМЫСЛ"},{"id":"IDEA_076","title_ru":"Провести неделю без доставки и сервисов «в один клик»","description_ru":"На неделю отказаться от части привычных удобств — готовить еду, ходить за покупками и решать бытовые задачи самостоятельно вместо того, чтобы делегировать их приложениям.","first_step_ru":"Выбери неделю и отметь, какими сервисами обычно пользуешься автоматически: доставка еды, продуктов, такси или другие услуги. Реши, от каких из них откажешься на эти семь дней.","category":"Skills","experience_type":"mastery_skill","impact":4,"accessibility":3,"novelty":3,"adventure":2,"travel":0,"physical":1,"learning":3,"creative":2,"social":1,"relationships":1,"courage":2,"freedom":3,"meaning":3,"budget":1,"time":2,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"ВЕРНУТЬ В ЖИЗНЬ БОЛЬШЕ САМОСТОЯТЕЛЬНОСТИ"},{"id":"IDEA_077","title_ru":"Вернуться в место из детства","description_ru":"Снова увидеть двор, улицу, школу, дачу или другое важное место спустя годы — и сравнить свои воспоминания с тем, каким оно стало сейчас.","first_step_ru":"Выбери одно место, с которым у тебя связано много детских воспоминаний, и запланируй день, чтобы туда вернуться.","category":"Meaning","experience_type":"memory_identity","impact":3,"accessibility":4,"novelty":2,"adventure":1,"travel":2,"physical":1,"learning":1,"creative":2,"social":2,"relationships":5,"courage":2,"freedom":3,"meaning":5,"budget":2,"time":2,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"ВЕРНУТЬСЯ К СВОЕЙ ИСТОРИИ"},{"id":"IDEA_078","title_ru":"Спросить родителей, какими они были в твоём возрасте","description_ru":"Узнать маму и папу не только как родителей, а как людей, у которых когда-то были те же вопросы, мечты, страхи, отношения и планы на будущее.","first_step_ru":"Подготовь 5–10 вопросов о том периоде их жизни, который соответствует твоему возрасту сейчас, и устрой отдельный разговор об этом.","category":"Relationships","experience_type":"relationships","impact":4,"accessibility":5,"novelty":3,"adventure":0,"travel":0,"physical":0,"learning":2,"creative":2,"social":3,"relationships":5,"courage":3,"freedom":2,"meaning":5,"budget":1,"time":1,"physical_level":1,"planning":2,"solo":false,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"УЗНАТЬ РОДИТЕЛЕЙ ПО-НОВОМУ"},{"id":"IDEA_079","title_ru":"Доверить другу придумать тебе приключение","description_ru":"На один день отказаться от планирования и позволить человеку, который хорошо тебя знает, полностью решить, куда вы отправитесь и что будете делать.","first_step_ru":"Выбери человека, которому доверяешь, назови дату, бюджет и свои границы — а всё остальное попроси оставить сюрпризом.","category":"Adventure","experience_type":"micro_adventure","impact":3,"accessibility":5,"novelty":4,"adventure":4,"travel":1,"physical":1,"learning":1,"creative":2,"social":5,"relationships":4,"courage":4,"freedom":5,"meaning":2,"budget":2,"time":1,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"ОТДАТЬ КОНТРОЛЬ НА ОДИН ДЕНЬ"},{"id":"IDEA_080","title_ru":"Устроить день спонтанных «да»","description_ru":"На один день чуть реже выбирать привычное «не сейчас» и быть открытым к неожиданным предложениям, новым местам и незапланированным идеям.","first_step_ru":"Выбери день и заранее определи свои границы — бюджет, безопасность и обязательства. А всему остальному попробуй чаще говорить «да».","category":"Adventure","experience_type":"courage_challenge","impact":4,"accessibility":5,"novelty":5,"adventure":4,"travel":1,"physical":1,"learning":1,"creative":2,"social":4,"relationships":3,"courage":4,"freedom":5,"meaning":2,"budget":2,"time":1,"physical_level":1,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"ДАТЬ СПОНТАННОСТИ БОЛЬШЕ МЕСТА"},{"id":"IDEA_081","title_ru":"Попробовать себя в гончарном деле","description_ru":"Почувствовать, как из обычного куска глины в твоих руках постепенно появляется настоящая вещь — пусть с первого раза совсем не идеальная.","first_step_ru":"Найди мастерскую с разовым занятием на гончарном круге и сделай свою первую чашку, тарелку или вазу.","category":"Creative","experience_type":"creative_project","impact":4,"accessibility":4,"novelty":4,"adventure":0,"travel":0,"physical":1,"learning":4,"creative":5,"social":2,"relationships":1,"courage":2,"freedom":2,"meaning":2,"budget":2,"time":2,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"СДЕЛАТЬ ЧТО-ТО РУКАМИ"},{"id":"IDEA_082","title_ru":"Научиться ездить верхом","description_ru":"Не просто прокатиться на лошади, а научиться чувствовать её движения, управлять ею и уверенно держаться в седле.","first_step_ru":"Найди конюшню с занятиями для новичков и запишись на первый полноценный урок верховой езды с инструктором.","category":"Physical","experience_type":"sport_adventure","impact":5,"accessibility":2,"novelty":5,"adventure":4,"travel":3,"physical":3,"learning":4,"creative":1,"social":2,"relationships":1,"courage":3,"freedom":3,"meaning":3,"budget":3,"time":2,"physical_level":2,"planning":2,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"ПОПРОБОВАТЬ НОВЫЙ ФИЗИЧЕСКИЙ ОПЫТ"},{"id":"IDEA_083","title_ru":"Попробовать скалолазание","description_ru":"Подняться по стене, используя только своё тело, технику и зацепки, — и почувствовать удовольствие от каждого метра, который ещё минуту назад казался невозможным.","first_step_ru":"Найди скалодром с занятиями для новичков и запишись на первый урок с инструктором и страховкой.","category":"Physical","experience_type":"sport_adventure","impact":5,"accessibility":4,"novelty":5,"adventure":4,"travel":2,"physical":5,"learning":5,"creative":1,"social":2,"relationships":1,"courage":5,"freedom":3,"meaning":3,"budget":3,"time":2,"physical_level":3,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":true,"list_only":false,"editorial_note":"Может быть №3 — конкретный более смелый опыт.","angle_ru":"ПРОВЕРИТЬ СЕБЯ НА ВЫСОТЕ"},{"id":"IDEA_085","title_ru":"Попробовать вейкборд","description_ru":"Почувствовать скорость на доске, научиться вставать из воды и проехать свои первые метры за катером или на лебёдке.","first_step_ru":"Найди вейк-парк или школу с занятиями для новичков и запишись на первую сессию с инструктором.","category":"Physical","experience_type":"sport_adventure","impact":5,"accessibility":2,"novelty":5,"adventure":4,"travel":1,"physical":5,"learning":4,"creative":1,"social":3,"relationships":1,"courage":4,"freedom":3,"meaning":2,"budget":2,"time":1,"physical_level":2,"planning":1,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":true,"list_only":false,"editorial_note":"Может быть №3 — конкретный более смелый опыт.","angle_ru":"ПОПРОБОВАТЬ НОВЫЙ СПОРТ"},{"id":"IDEA_088","title_ru":"Уехать на день туда, куда обычно кажется слишком далеко","description_ru":"Превратить обычный свободный день в маленькое путешествие и наконец добраться до места, которое ты постоянно откладываешь «на потом».","first_step_ru":"Выбери место в 2–3 часах пути, куда давно хочется попасть, и назначь конкретный день для поездки — даже если дорога займёт почти столько же времени, сколько сама прогулка.","category":"Travel","experience_type":"travel","impact":5,"accessibility":2,"novelty":5,"adventure":4,"travel":5,"physical":1,"learning":1,"creative":1,"social":2,"relationships":1,"courage":3,"freedom":4,"meaning":2,"budget":2,"time":1,"physical_level":2,"planning":1,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"РАСШИРИТЬ СВОЮ КАРТУ"},{"id":"IDEA_089","title_ru":"Отправиться в спонтанное путешествие","description_ru":"Хотя бы раз не планировать поездку за недели или месяцы, а решить сегодня — и уже завтра оказаться в новом месте.","first_step_ru":"Заранее определи только бюджет и максимальное время в дороге. В один свободный вечер выбери направление, купи билет — и отправляйся на следующий день.","category":"Adventure","experience_type":"travel","impact":4,"accessibility":2,"novelty":5,"adventure":5,"travel":5,"physical":1,"learning":1,"creative":1,"social":2,"relationships":1,"courage":5,"freedom":5,"meaning":2,"budget":2,"time":1,"physical_level":2,"planning":1,"solo":true,"with_people":true,"travel_required":true,"active":true,"top1":true,"top2":false,"stretch":true,"list_only":false,"editorial_note":"Может быть №1 — ТВОЙ NEXT CHAPTER.","angle_ru":"ДОВЕРИТЬСЯ ИМПУЛЬСУ"},{"id":"IDEA_091","title_ru":"Сходить на мастер-класс к профессиональному шефу","description_ru":"Не просто попробовать новое блюдо, а узнать, как его готовит профессионал, освоить несколько приёмов и повторить всё своими руками.","first_step_ru":"Выбери то, чему тебе действительно хочется научиться — пасту, суши, десерт, коктейли или что-то сложнее — и найди мастер-класс у шефа или другого профессионала.","category":"Food","experience_type":"mastery_skill","impact":4,"accessibility":3,"novelty":3,"adventure":2,"travel":1,"physical":1,"learning":4,"creative":4,"social":4,"relationships":1,"courage":2,"freedom":2,"meaning":3,"budget":2,"time":1,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"ПОДНЯТЬ ОБЫЧНЫЙ ИНТЕРЕС НА НОВЫЙ УРОВЕНЬ"},{"id":"IDEA_094","title_ru":"Устроить вечер старых фотографий с близкими","description_ru":"Вместе пересмотреть старые снимки, вспомнить людей, места и истории, о которых в обычной жизни вы почти никогда не говорите.","first_step_ru":"Выберите вечер и попроси каждого принести любимые старые фотографии. Смотрите их вместе и записывайте истории, которые особенно хочется сохранить.","category":"Relationships","experience_type":"relationships","impact":4,"accessibility":4,"novelty":3,"adventure":0,"travel":0,"physical":0,"learning":1,"creative":2,"social":4,"relationships":5,"courage":1,"freedom":2,"meaning":5,"budget":1,"time":1,"physical_level":1,"planning":2,"solo":false,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":false,"stretch":false,"list_only":true,"editorial_note":"Только 4–20: микроидея или слишком абстрактная формулировка для витрины Top 3.","angle_ru":"ВЕРНУТЬСЯ К ОБЩИМ ВОСПОМИНАНИЯМ"},{"id":"IDEA_100","title_ru":"Сделать доброе дело анонимно","description_ru":"Помочь кому-то так, чтобы не получить за это благодарности, признания или даже возможности увидеть реакцию — просто потому, что можешь сделать чей-то день немного лучше.","first_step_ru":"Подумай, кому сейчас могла бы пригодиться небольшая помощь, и придумай способ сделать её анонимно — оплатить что-то, оставить подарок, сделать пожертвование или решить маленькую проблему.","category":"Meaning","experience_type":"meaning_contribution","impact":4,"accessibility":3,"novelty":3,"adventure":1,"travel":0,"physical":0,"learning":1,"creative":2,"social":2,"relationships":4,"courage":3,"freedom":3,"meaning":5,"budget":2,"time":1,"physical_level":1,"planning":2,"solo":true,"with_people":true,"travel_required":false,"active":true,"top1":false,"top2":true,"stretch":false,"list_only":false,"editorial_note":"Может быть №2 — конкретная сильная рекомендация.","angle_ru":"СДЕЛАТЬ ДОБРО БЕЗ ПУБЛИЧНОСТИ"}];

